import csv
import json
from datetime import datetime, date, time, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
from zoneinfo import ZoneInfo

ORDER_DATE = date(2026, 9, 25)
ORDER_TIME_BUYER = datetime(2026, 9, 25, 14, 40, tzinfo=ZoneInfo("America/Chicago"))
BUYER_CITY = "Phenix City"
BUYER_STATE = "AL"
DELIVERY_FEE = Decimal("9.99")
BASE_DIR = Path("/app")
INPUT_DIR = BASE_DIR / "input"

def money(value):
    return Decimal(value).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

# Catalogue
catalogue = {}
with open(INPUT_DIR / "cord_catalogue.csv", newline="") as f:
    for row in csv.DictReader(f):
        sku = row["sku"]
        catalogue[sku] = {
            "sku": sku,
            "supplier_part": row["supplier_part"],
            "connector": row["connector"],
            "polarized": row["polarized"],
            "length_ft": int(row["length_ft"]),
            "conductor_awg": int(row["conductor_awg"]),
            "price_usd": Decimal(row["price_usd"]),
        }

# Store directory: choose latest effective row on or before order date
store_rows = []
with open(INPUT_DIR / "store_directory.csv", newline="") as f:
    for row in csv.DictReader(f):
        row["_effective_from"] = datetime.strptime(row["effective_from"], "%Y-%m-%d").date()
        row["distance_mi"] = Decimal(row["distance_mi"])
        row["sales_tax_pct"] = Decimal(row["sales_tax_pct"])
        store_rows.append(row)

stores = {}
for row in store_rows:
    if row["_effective_from"] <= ORDER_DATE:
        stores[row["store_id"]] = row

# Tax jurisdictions
tax_rates = {}
with open(INPUT_DIR / "tax_jurisdictions.csv", newline="") as f:
    for row in csv.DictReader(f):
        tax_rates[(row["city"], row["state"])] = Decimal(row["combined_sales_tax_pct"])

# Stock ledger
ledger = []
with open(INPUT_DIR / "stock_ledger.csv", newline="") as f:
    for row in csv.DictReader(f):
        row["_posted"] = datetime.strptime(row["posted_local"], "%Y-%m-%d %H:%M")
        row["qty"] = int(row["qty"])
        ledger.append(row)

def fit_reason(cord):
    if cord["connector"] != "C7":
        return "FIT_CONNECTOR"
    if cord["polarized"] == "Y":
        return "FIT_POLARIZED"
    if cord["length_ft"] > 6 and cord["conductor_awg"] > 18:
        return "FIT_GAUGE"
    if cord["length_ft"] < 10 or cord["length_ft"] > 15:
        return "FIT_LENGTH"
    return "NONE"

def effective_stock(store_id, sku, order_local_naive):
    cord = catalogue[sku]
    codes = {sku, cord["supplier_part"]}
    opening_dt = None
    base = 0
    for row in ledger:
        if row["store_id"] != store_id or row["item_code"] not in codes:
            continue
        if row["event"] == "OPENING" and row["_posted"].date() == ORDER_DATE:
            base = row["qty"]
            opening_dt = row["_posted"]
    for row in ledger:
        if row["store_id"] != store_id or row["item_code"] not in codes:
            continue
        if row["event"] == "OPENING":
            continue
        if row["_posted"].date() != ORDER_DATE:
            continue
        if opening_dt is not None and row["_posted"] <= opening_dt:
            continue
        if row["_posted"] > order_local_naive:
            continue
        if row["event"] in ("OPENING", "RECEIPT", "VOID"):
            base += row["qty"]
        elif row["event"] in ("SALE", "HOLD", "TRANSFER_OUT"):
            base -= row["qty"]
    return base

def cutoff_for(store_id, method):
    # Notices for 2026-09-25
    if store_id == "ST-08" and method == "PICKUP":
        return time(16, 0)
    return time(15, 0)

def method_paused(store_id, method):
    if store_id == "ST-52" and method == "DELIVERY":
        return True
    return False

offers = []
with open(INPUT_DIR / "same_day_offers.csv", newline="") as f:
    for row in csv.DictReader(f):
        offers.append(row)

evaluated = []
eligible = []
for offer in offers:
    offer_id = offer["offer_id"]
    store_id = offer["store_id"]
    sku = offer["sku"]
    method = offer["method"]
    store = stores[store_id]
    cord = catalogue[sku]

    store_tz = ZoneInfo(store["timezone"])
    order_local = ORDER_TIME_BUYER.astimezone(store_tz).replace(tzinfo=None)
    order_ready_local = order_local + timedelta(hours=2)

    reason = fit_reason(cord)
    stock = None
    if reason == "NONE":
        stock = effective_stock(store_id, sku, order_local)
        if stock < 1:
            reason = "NO_STOCK"
        elif method == "DELIVERY" and stock < 2:
            reason = "STOCK_RESERVE"
        elif store["same_day_suspended"] == "Y" or method_paused(store_id, method):
            reason = "SAME_DAY_SUSPENDED"
        elif order_local.time() >= cutoff_for(store_id, method):
            reason = "CUTOFF_PASSED"
        elif method == "DELIVERY" and store["distance_mi"] > 10:
            reason = "OUT_OF_RADIUS"
        else:
            reason = "NONE"

    landed = ""
    if reason == "NONE":
        price = cord["price_usd"]
        if method == "PICKUP":
            rate = store["sales_tax_pct"]
        else:
            rate = tax_rates[(BUYER_CITY, BUYER_STATE)]
        taxed = money(price * (Decimal("1") + rate / Decimal("100")))
        if method == "DELIVERY":
            landed = money(taxed + DELIVERY_FEE)
        else:
            landed = money(taxed)

        ready_utc = order_ready_local.astimezone(store_tz).astimezone(timezone.utc)
        eligible.append({
            "offer_id": offer_id,
            "landed": landed,
            "ready_utc": ready_utc,
            "distance_mi": store["distance_mi"],
        })

    evaluated.append({
        "offer_id": offer_id,
        "decision": "ELIGIBLE" if reason == "NONE" else "INELIGIBLE",
        "reason_code": reason,
        "landed_cost_usd": landed,
    })

# Write CSV
with open(BASE_DIR / "offer_evaluation.csv", "w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=["offer_id", "decision", "reason_code", "landed_cost_usd"])
    writer.writeheader()
    for row in evaluated:
        writer.writerow(row)

# Choose best eligible offer
if eligible:
    chosen = min(eligible, key=lambda x: (x["landed"], x["ready_utc"], x["distance_mi"], x["offer_id"]))
else:
    chosen = {"offer_id": "", "landed": Decimal("0")}

results = {
    "eligible_offer_count": len(eligible),
    "chosen_offer_id": chosen["offer_id"],
    "chosen_total_usd": float(chosen["landed"]),
}

with open(BASE_DIR / "results.json", "w") as f:
    json.dump(results, f, indent=2)
    f.write("\n")

# Print a verification table
print(f"{'offer':6} {'decision':10} {'reason':20} {'landed':8} stock")
for row in evaluated:
    print(f"{row['offer_id']:6} {row['decision']:10} {row['reason_code']:20} {str(row['landed_cost_usd']):8}")
print("Results:", results)
